-- HTS / Schedule B / cross-reference sync 2026-11-27 (part 1 of 1). Generated by scripts/sync-bulk-data.ts from the official files:
-- first-time chapters are replaced as a whole, later ones change only the lines that differ. Statements are keyed by row id, so re-running is harmless.

PRAGMA defer_foreign_keys = on;
DELETE FROM hts_path_search WHERE rowid IN (SELECT id FROM hts_lines WHERE chapter = '15');
DELETE FROM hts_lines WHERE chapter = '15';
WITH RECURSIVE anc(leaf, node, depth) AS (
  SELECT id, superior_id, 1 FROM hts_lines WHERE chapter = '15' AND htsno != '' AND superior_id IS NOT NULL
  UNION ALL
  SELECT anc.leaf, h.superior_id, anc.depth + 1
  FROM anc JOIN hts_lines h ON h.id = anc.node
  WHERE h.superior_id IS NOT NULL AND anc.depth < 8
)
SELECT anc.leaf, group_concat(h.description, ' ')
FROM anc JOIN hts_lines h ON h.id = anc.node
GROUP BY anc.leaf;
